class Solution:
    def tfIdf(self, docs: List[str], vocab: List[str]) -> List[List[float]]:
        n_docs = len(docs)
        counts = [Counter(doc.split()) for doc in docs]
        lengths = [sum(c.values()) for c in counts]
        df = Counter()
        for c in counts:
            for word in c:
                df[word] += 1
        idf = {w: math.log((1 + n_docs) / (1 + df[w])) + 1.0 for w in vocab}
        vectors = []
        for c, length in zip(counts, lengths):
            if length == 0:
                vectors.append([0.0] * len(vocab))
                continue
            vectors.append([c[w] / length * idf[w] for w in vocab])
        return vectors

